steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      users {
        nodes {
          id
          name
          email
        }
      }
      comments(orderBy: createdAt) {
        nodes {
          id
          body
          createdAt
          user {
            name
            email
          }
          issue {
            id
            identifier
            title
            priority
            state {
              name
              type
            }
            assignee {
              name
            }
            team {
              name
            }
          }
        }
      }
    }"
  }' | python3 -m json.tool
